# Find hairpin loops (regions of unpaired between a pair)
# For each pair (i,j), if i+1..j-1 contains no nested pairs, it's a hairpin
def find_hairpins():
    hp=[]
    for i in range(n):
        if pairs[i] is not None and i < pairs[i]:
            j = pairs[i]
            # check if any pair strictly inside
            inner = any(pairs[k] is not None and k>i and k<j for k in range(i+1,j))
            if not inner:
                hp.append((i,j))
    return hp
hps = find_hairpins()
print("num hairpin pairs (deepest)", len(hps))
